CREATE TABLE option_groups (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),merchant_id UUID NOT NULL REFERENCES merchants(id),name VARCHAR(160) NOT NULL,description VARCHAR(255),selection_type VARCHAR(20) NOT NULL,required BOOLEAN NOT NULL DEFAULT false,minimum_selections INTEGER NOT NULL DEFAULT 0,maximum_selections INTEGER,active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(selection_type IN ('SINGLE','MULTIPLE')),CHECK(minimum_selections>=0),CHECK(maximum_selections IS NULL OR maximum_selections>=minimum_selections),CHECK(selection_type<>'SINGLE' OR maximum_selections IS NULL OR maximum_selections<=1));
CREATE TABLE option_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),option_group_id UUID NOT NULL REFERENCES option_groups(id),name VARCHAR(160) NOT NULL,price_adjustment NUMERIC(12,2) NOT NULL DEFAULT 0,available BOOLEAN NOT NULL DEFAULT true,active BOOLEAN NOT NULL DEFAULT true,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(price_adjustment>=0));
CREATE TABLE product_option_groups (product_id UUID NOT NULL REFERENCES products(id),option_group_id UUID NOT NULL REFERENCES option_groups(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(product_id,option_group_id));
CREATE TABLE branch_products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),branch_id UUID NOT NULL REFERENCES branches(id),product_id UUID NOT NULL REFERENCES products(id),available BOOLEAN NOT NULL DEFAULT true,override_price NUMERIC(12,2),stock_quantity NUMERIC(12,3),preparation_time_minutes INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(branch_id,product_id),CHECK(override_price IS NULL OR override_price>=0),CHECK(stock_quantity IS NULL OR stock_quantity>=0));
CREATE TABLE price_lists (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),merchant_id UUID NOT NULL REFERENCES merchants(id),name VARCHAR(160) NOT NULL,code VARCHAR(80) NOT NULL,currency VARCHAR(3) NOT NULL,active BOOLEAN NOT NULL DEFAULT true,valid_from TIMESTAMPTZ,valid_to TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,merchant_id,code),CHECK(currency ~ '^[A-Z]{3}$'),CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>valid_from));
CREATE TABLE price_list_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id),price_list_id UUID NOT NULL REFERENCES price_lists(id),product_id UUID REFERENCES products(id),variant_id UUID REFERENCES product_variants(id),price NUMERIC(12,2) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((product_id IS NULL)<>(variant_id IS NULL)),CHECK(price>=0));
CREATE UNIQUE INDEX uq_price_item_product ON price_list_items(price_list_id,product_id) WHERE product_id IS NOT NULL;
CREATE UNIQUE INDEX uq_price_item_variant ON price_list_items(price_list_id,variant_id) WHERE variant_id IS NOT NULL;
